/*
 * A223081  Numbers n with distinct digits such that n divides the reversal of
 *          n.
 * https://oeis.org/A223081
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full, base
 * Formula:   a(n) is generated by exhaustive search over all positive
 *            integers with distinct decimal digits (no leading or trailing
 *            zero) that divide their own decimal reversal. The numbers are
 *            generated in strictly increasing numeric order and the n‑th such
 *            number is returned. No hardcoded table is used; the...
 * Range:     u8 n <= 9, u16 n <= 11, u32 n <= 12, u64 n <= 12, u128 n <= 12,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdint.h>

/* Recursive search ----------------------------------------------------- */
static idx_t            target   = 0;  /* index to find (1‑based) */
static idx_t            counter  = 0;  /* how many terms found so far   */
static seq_t            answer   = 0;  /* found term                    */
static bool             found    = false;

/* Reverse the decimal digits of x.  Works for any seq_t type. */
static seq_t rev_decimal(seq_t x)
{
    seq_t rev = 0;
    while (x > 0) {
        seq_t d = x % 10;
        rev = rev * 10 + d;
        x   = x / 10;
    }
    return rev;
}

/* Depth‑first search that builds numbers of a fixed length.
   Parameters:
   pos     – current position (0‑based)
   len     – target length of the number
   used    – bitmask of digits already used
   val     – value of the prefix built so far */
static void dfs(int pos, int len, uint32_t used, seq_t val)
{
    if (found) return;

    if (pos == len) {
        seq_t rev = rev_decimal(val);
        if (rev % val == 0) {
            ++counter;
            if (counter == target) {
                answer = val;
                found  = true;
            }
        }
        return;
    }

    for (int d = 0; d <= 9; ++d) {
        if (used & (1U << d)) continue;          /* digit already used */
        if (pos == 0 && d == 0) continue;         /* no leading zero   */
        if (pos == len - 1 && d == 0) continue;   /* no trailing zero  */
        seq_t new_val = val * 10 + d;
        dfs(pos + 1, len, used | (1U << d), new_val);
        if (found) return;
    }
}

/* --------------------------------------------------------------------- */
/* Public function required by the problem statement.                     */
/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n < 1) return 0;        /* out of range (offset starts at 1) */

    target  = n;
    counter = 0;
    answer  = 0;
    found   = false;

    /* All numbers with distinct digits have at most 10 digits. */
    for (int len = 1; len <= 10; ++len) {
        dfs(0, len, 0, 0);
        if (found) break;
    }

    return answer;   /* returns 0 if n exceeds the number of terms   */
}
